import { useState } from "react";
import axios from "axios";

const symptomsList = [
  "itching","skin_rash","fever","cough","headache","nausea","vomiting",
  "fatigue","weight_loss","chest_pain","breathlessness","abdominal_pain",
  "diarrhoea","constipation","dizziness","muscle_pain","joint_pain",
  "sore_throat","runny_nose","sweating","loss_of_appetite"
];

function MedicalForm() {
  const [age, setAge] = useState("");
  const [gender, setGender] = useState("");
  const [duration, setDuration] = useState("");
  const [selectedSymptoms, setSelectedSymptoms] = useState([]);
  const [result, setResult] = useState(null);

  const toggleSymptom = (symptom) => {
    if (selectedSymptoms.includes(symptom)) {
      setSelectedSymptoms(selectedSymptoms.filter(s => s !== symptom));
    } else {
      setSelectedSymptoms([...selectedSymptoms, symptom]);
    }
  };

  const submit = async () => {
    const res = await axios.post("http://127.0.0.1:5000/predict", {
      symptoms: selectedSymptoms,
      age,
      gender,
      duration
    });

    setResult(res.data);
  };

  return (
    <div style={{padding:"30px", fontFamily:"Arial"}}>
      <h1>🩺 Medical Symptom Questionnaire</h1>

      <h3>Personal Information</h3>
      Age: <input type="number" onChange={e=>setAge(e.target.value)} /><br/><br/>

      Gender:
      <select onChange={e=>setGender(e.target.value)}>
        <option>Select</option>
        <option>Male</option>
        <option>Female</option>
      </select><br/><br/>

      Duration of Symptoms (days):
      <input type="number" onChange={e=>setDuration(e.target.value)} /><br/><br/>

      <h3>Select All Symptoms You Have</h3>
      {symptomsList.map(sym => (
        <div key={sym}>
          <input type="checkbox" onChange={()=>toggleSymptom(sym)} /> {sym}
        </div>
      ))}

      <br/>
      <button onClick={submit}>Submit Form</button>

      {result && (
        <div style={{marginTop:"20px", padding:"15px", border:"2px solid black"}}>
          <h2>Prediction Result</h2>
          <h3>Disease: {result.disease}</h3>
          <h3>Urgency: {result.urgency}</h3>
          <h3>Confidence: {result.confidence}%</h3>

          {result.urgency === "High" && (
            <h2 style={{color:"red"}}>⚠️ Visit Doctor Immediately!</h2>
          )}
        </div>
      )}
    </div>
  );
}

export default MedicalForm;
